-- Migración de la cotización INDUAMERICA 230825.
-- Conserva 332 partidas como maestro de inventario y las 72 cantidades seleccionadas como existencias iniciales.

alter table public.inventory_items
  add column if not exists unit_cost numeric,
  add column if not exists currency text not null default 'PEN';

insert into public.measurement_units (id, name, symbol)
values ('unit-und', 'Unidad', 'und')
on conflict (id) do update set name = excluded.name, symbol = excluded.symbol;

insert into public.brands (id, name)
values ('brand-induamerica', 'INDUAMERICA')
on conflict (id) do update set name = excluded.name;

insert into public.product_families (id, name)
values ('family-furgones', 'Furgones')
on conflict (name) do update set active = true;

