insert into public.inventory_items (id, code, category, category_id, description, physical, committed, safety, unit, unit_id, brand_id, location, unit_cost, currency)
select 'inv-' || code, code, category, "categoryId", description, physical, 0, 0, 'und', 'unit-und', 'brand-induamerica', 'MIG-INDUAMERICA', "unitCost", 'PEN' from materials
on conflict (code) do update set
  category = excluded.category, category_id = excluded.category_id, description = excluded.description,
  physical = excluded.physical, unit_cost = excluded.unit_cost, currency = excluded.currency,
  brand_id = excluded.brand_id, location = excluded.location;

insert into public.inventory_movements (id, type, code, ceco, quantity, note)
