insert into public.body_types (id, code, family, family_id, brand_id, name, target_days, output_unit, output_unit_id)
select 'body-ind-furgon-08', 'PROD-IND-08', family.name, family.id, 'brand-induamerica', 'Furgón acanalado vertical · 08 palets · 5 TN', 15, 'und', 'unit-und'
from public.product_families family where lower(family.name) = 'furgones'
on conflict (id) do update set code = excluded.code, family = excluded.family, family_id = excluded.family_id, brand_id = excluded.brand_id, name = excluded.name, target_days = excluded.target_days, output_unit = excluded.output_unit, output_unit_id = excluded.output_unit_id;

delete from public.product_routes where product_id = 'body-ind-furgon-08';
