), supply_stage as (select id from public.flow_stages order by "order" limit 1)
insert into public.bom_items (id, body_type_id, stage_id, material_code, piece_code, description, length_mm, quantity)
select 'bom-ind-' || lpad(row_number() over (order by code)::text, 3, '0'), 'body-ind-furgon-08', supply_stage.id, code, 'IND-' || lpad(row_number() over (order by code)::text, 3, '0'), description, 0, physical
from selected cross join supply_stage
on conflict (id) do update set material_code = excluded.material_code, piece_code = excluded.piece_code, description = excluded.description, quantity = excluded.quantity, stage_id = excluded.stage_id;
